export async function clearPersistedTheme(page) {
    await page.evaluate(() => { localStorage.removeItem('excalidraw-theme'); return 'cleared'; });
}

export async function openMainMenu(page) {
    await page.getByTestId("main-menu-trigger").click();
}

export async function selectTheme(page, themeOptionName) {
    await page.getByTestId("dropdown-menu").getByRole("radio", { name: themeOptionName }).click();
}

export async function openImageExportDialog(page) {
    await page.getByTestId("image-export-button").click();
}

export async function toggleExportDarkMode(page) {
    await page.getByRole("checkbox", { name: "Dark mode" }).click();
}
